#include "business_store.hpp"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <QFile>
#include <QCryptographicHash>
#include <QTextStream>
static void check(bool ok,const char*why){if(!ok)throw std::runtime_error(why);}
static QByteArray bytes(QString path){QFile f(path);check(f.open(QIODevice::ReadOnly),"fixture file");return f.readAll();}
int main(int argc,char**argv){QCoreApplication app(argc,argv);try{check(argc==2,"isolated root required");QTemporaryDir temp(QString(argv[1])+"/ledger-XXXXXX");check(temp.isValid(),"isolated directory");QString file=temp.path()+"/business.sqlite";bool failed=false;try{BusinessStore::readLedgerSnapshot(file);}catch(...){failed=true;}check(failed&&!QFile::exists(file),"missing source never created");auto writer=QSqlDatabase::addDatabase("QSQLITE","writer");writer.setDatabaseName(file);check(writer.open(),"fixture open");QSqlQuery q(writer);check(q.exec("PRAGMA journal_mode=WAL"),"WAL fixture");check(q.exec("CREATE TABLE records(kind TEXT,id TEXT,payload TEXT,PRIMARY KEY(kind,id))"),"fixture schema");check(q.exec("INSERT INTO records VALUES('accounts','A','{\"id\":\"A\",\"type\":\"ledger\",\"name\":\"before\"}')"),"account fixture");check(q.exec("INSERT INTO records VALUES('trades','T','{\"id\":\"T\",\"quantity\":100}')"),"trade fixture");
 int checks=0;bool wrote=false;auto snap=BusinessStore::readLedgerSnapshot(file,[&]{if(++checks==4){check(q.exec("UPDATE records SET payload='{\"id\":\"T\",\"quantity\":200}' WHERE kind='trades'"),"concurrent fixture write");wrote=true;}return false;});check(wrote&&snap["accounts"].toArray().size()==1&&snap["trades"].toArray()[0].toObject()["quantity"]==100,"accounts and trades from one read transaction");auto after=BusinessStore::readLedgerSnapshot(file);check(after["trades"].toArray()[0].toObject()["quantity"]==200,"later read sees committed change");failed=false;try{BusinessStore::readLedgerSnapshot(file,[]{return true;});}catch(...){failed=true;}check(failed,"cancelled read");q.finish();writer.close();auto before=bytes(file);BusinessStore::readLedgerSnapshot(file);check(bytes(file)==before,"read does not write source file");writer={};QSqlDatabase::removeDatabase("writer");QTextStream(stdout)<<"PASS ledger readonly: missing, same-transaction concurrent writer, subsequent version, cancellation, unchanged source bytes\n";return 0;}catch(const std::exception&e){QTextStream(stderr)<<e.what()<<'\n';return 1;}}
